        if (nx, ny) in obstacles:
            continue

        d_center = abs(nx - cx) + abs(ny - cy)
        d_opp = dist(nx, ny, ox, oy)
        v = -d_center + 0.6 * d_opp
        if (nx, ny) in unclaimed:
            v += 6.0
            # Prefer grabbing cells that are farther from opponent to reduce immediate flips
            v += 0.15 * d_opp
        elif (nx, ny) in self_set:
            v += 3.0
        elif (nx, ny) in opp_set:
            # Counterclaim only if it also moves us toward center
            v += 1.5 - 0.03 * d_center
        else:
            v += 0.5

        # Small deterministic tie-breaker: prefer moves that increase x then y then stay
        tiebreak = (nx, ny)
        if v > best_v or (v == best_v and (best is None or tiebreak > best)):
            best_v = v
            best = tiebreak
            best_move = (dx, dy)

    return [int(best_move[0]), int(best_move[1])]

